import React, { useState } from "react";
import { TriangleAlert, CodeXml } from "lucide-react";
import { LANE_COLORS, GRADE_COLORS, GRADE_SHORT_LABELS, TITLE_COLORS } from "../constants.js";

export function LaneBadge({ lane, size = "md" }) {
  const c = LANE_COLORS[lane] || { bg: "#3D5266", fg: "#EAF1F7", ring: "#3D5266" };
  const cls = size === "xs" ? "w-4 h-4 text-[9px]" : size === "sm" ? "w-5 h-5 text-[10px]" : "w-7 h-7 text-sm";
  return (
    <span
      style={{ background: c.bg, color: c.fg, border: `1px solid ${c.ring}` }}
      className={`inline-flex items-center justify-center rounded-md font-bold shrink-0 ${cls}`}
    >
      {lane ?? "―"}
    </span>
  );
}

export function GradeBadge({ grade, short = false }) {
  if (!grade) return null;
  const c = GRADE_COLORS[grade] || GRADE_COLORS["一般"];
  return (
    <span style={{ background: c.bg, color: c.fg }} className="inline-block px-1.5 py-0.5 rounded text-[10px] font-bold leading-none whitespace-nowrap">
      {short ? (GRADE_SHORT_LABELS[grade] || grade) : grade}
    </span>
  );
}

export function TitleBadge({ title }) {
  if (!title) return null;
  const key = String(title).includes("優勝戦") ? "優勝戦" : String(title).includes("準優") ? "準優勝戦" : "予選";
  const c = TITLE_COLORS[key];
  return (
    <span style={{ background: c.bg, color: c.fg, border: `1px solid ${c.ring}` }} className="inline-block px-1.5 py-0.5 rounded text-[10px] font-bold leading-none">
      {title}
    </span>
  );
}

export function ClassBadge({ text }) {
  if (!text) return null;
  const t = String(text).toUpperCase();
  const color = t.includes("A1") ? "#F2A93B" : t.includes("A2") ? "#E5C158" : t.includes("B1") ? "#7FA6C9" : "#8B98A8";
  return <span style={{ background: color }} className="inline-block px-1.5 py-0.5 rounded text-[10px] font-bold text-[#12283C] leading-none">{t}</span>;
}

export function Stat({ label, value, unit }) {
  const empty = value === undefined || value === null || value === "" || Number.isNaN(value);
  return (
    <div className="flex flex-col items-end leading-tight">
      <span className="text-[10px] text-sub2">{label}</span>
      <span className="text-sm font-semibold tabular-nums text-ink">{empty ? "―" : `${value}${unit || ""}`}</span>
    </div>
  );
}

export function Notice({ children, tone = "info" }) {
  const border = tone === "warn" ? "border-[#F2A93B]/50" : "border-line";
  return (
    <div className={`flex items-start gap-2 text-xs text-sub2 bg-panel border border-dashed ${border} rounded-lg p-3`}>
      <TriangleAlert size={14} className="shrink-0 mt-0.5" />
      <div className="leading-relaxed">{children}</div>
    </div>
  );
}

export function SectionLabel({ children }) {
  return <div className="text-[11px] font-semibold text-accent mb-1.5">{children}</div>;
}

export function Spinner({ label }) {
  return (
    <div className="flex flex-col items-center justify-center py-10 gap-3">
      <div className="w-6 h-6 border-2 border-line border-t-accent rounded-full animate-spin" />
      {label && <span className="text-xs text-sub">{label}</span>}
    </div>
  );
}

export function RawJson({ data, label = "生JSONを見る（フィールド名確認用）" }) {
  const [open, setOpen] = useState(false);
  if (!data) return null;
  return (
    <div className="mt-3">
      <button onClick={() => setOpen((o) => !o)} className="flex items-center gap-1 text-[11px] text-sub2 hover:text-accent transition-colors">
        <CodeXml size={12} />
        {open ? "生JSONを隠す" : label}
      </button>
      {open && (
        <pre className="mt-2 max-h-64 overflow-auto bg-base border border-line rounded-md p-2 text-[10px] text-sub whitespace-pre-wrap break-all">
          {JSON.stringify(data, null, 2)}
        </pre>
      )}
    </div>
  );
}

export function fmtPct(v, digits = 1) {
  return Number.isFinite(v) ? `${v.toFixed(digits)}%` : "―";
}
