import React, { useEffect, useMemo, useState } from "react";
import { Calculator, RefreshCw, Loader2 } from "lucide-react";
import { BET_TYPES, comboKey, syntheticOdds, oddsBandColor, ODDS_BANDS as ODDS_LEGEND } from "../lib/odds.js";
import { PROXY_BASE } from "../lib/api.js";
import { LANE_COLORS } from "../constants.js";
import { LaneBadge, Notice } from "./ui.jsx";

/**
 * オッズ画面。
 *
 * オッズタブを開いたとき、および開催場・レース・日付が変わったときに、
 * 取得用プロキシ（lib/api.js の PROXY_BASE。既定はローカルの
 * uipath-server=http://localhost:5001、.env で REACT_APP_PROXY_BASE を
 * 設定すればデプロイした cf-worker）経由で公式サイト（boatrace.jp）の
 * 単勝・複勝・拡連複・2連単・2連複・3連単・3連複オッズをまとめて自動取得する。
 * ブラウザから公式サイトを直接fetchするとCORSで拒否されるため、
 * プロキシを1枚挟んでいる。プロキシが動いていない/公式サイトのボット対策で
 * ブロックされた場合は失敗するので、その場合は「再取得」を試す。
 *
 * オッズの行をタップすると選択でき、複数選択すると下の「合成オッズ」に
 * 反映される。複勝・拡連複はオッズに幅があるため、内部的には下限値を
 * 数値として保持し（並び替え・合成オッズ計算のため）、実際の幅は別途
 * 注記として表示する。
 */

function lowerBoundOf(v) {
  if (typeof v === "number") return v;
  const m = String(v ?? "").match(/^([\d.]+)/);
  return m ? Number(m[1]) : NaN;
}

const LANES = [1, 2, 3, 4, 5, 6];

/**
 * 公式サイト（boatrace.jp/BOATCAST）のオッズ表の見た目を踏襲した表示。
 * 軸（1着候補）ごとに縦長のブロックを横に6つ並べ、各ブロックの見出しに
 * 枠番の色＋選手名を出す。ブロック内は式別ごとに中身が変わる：
 *   - 単勝・複勝: 軸自身のオッズ1つだけ
 *   - 2連単・2連複・拡連複: 相手艇ぶんの行を縦に並べる
 *   - 3連複: 2着候補（軸より大きい艇番のみ、順不同の重複を避けるため）を
 *     見出し行にして、その下に3着候補の行を並べる
 *   - 3連単: 2着候補ごとに、その2連単オッズと、残り3着ぶんの3連単オッズを
 *     合成した参考値（syntheticOdds）を見出しとして出し、下に3着ごとの
 *     3連単オッズを並べる（2連単を買うのと3連単を割って買うのとで
 *     どちらが有利かの目安になる）。
 * 横に長くなるため、ブロック全体を横スクロールできるようにしている。
 */
function AxisHeader({ axis, name }) {
  const c = LANE_COLORS[axis] || { bg: "#3D5266", fg: "#EAF1F7" };
  return (
    <div className="flex items-center gap-1 px-1.5 py-1" style={{ background: c.bg, color: c.fg }}>
      <span className="font-bold text-[11px] tabular-nums shrink-0">{axis}</span>
      <span className="text-[10px] font-semibold truncate">{name}</span>
    </div>
  );
}

function OddsRow({ lane, value, isRange, selected, onToggle, borderTop = true }) {
  const c = oddsBandColor(value);
  return (
    <button
      onClick={onToggle}
      className={
        "w-full flex items-center justify-between gap-1 px-1.5 py-1 " +
        (borderTop ? "border-t border-line " : "") +
        (selected ? "bg-line" : "hover:bg-line/40")
      }
    >
      <LaneBadge lane={lane} size="xs" />
      <span className="text-[11px] font-bold tabular-nums" style={{ color: c.bg }}>
        {isRange ? (value ? String(value) : "―") : Number.isFinite(value) ? value.toFixed(1) : "―"}
      </span>
    </button>
  );
}

/** 単勝・複勝: 軸ブロックの中身は自分自身のオッズ1つだけ。 */
function SingleAxisBoard({ odds, boatNames, isRange }) {
  return (
    <div className="flex gap-1.5 overflow-x-auto pb-1">
      {LANES.map((axis) => {
        const v = odds[String(axis)];
        const c = oddsBandColor(v);
        return (
          <div key={axis} className="shrink-0 w-24 bg-base border border-line rounded-md overflow-hidden">
            <AxisHeader axis={axis} name={boatNames?.[axis - 1] || ""} />
            <div className="text-center py-2.5">
              <span className="text-sm font-bold tabular-nums" style={{ color: c.bg }}>
                {isRange ? (v ? String(v) : "―") : Number.isFinite(v) ? v.toFixed(1) : "―"}
              </span>
              <span className="text-[9px] text-sub2 ml-0.5">倍</span>
            </div>
          </div>
        );
      })}
    </div>
  );
}

/** 2連単・2連複・拡連複: 軸ブロックの中に相手艇ぶんの行を縦に並べる。 */
function PairAxisBoard({ type, odds, boatNames, isRange, restrictGreater, selected, toggle }) {
  return (
    <div className="flex gap-1.5 overflow-x-auto pb-1">
      {LANES.map((axis) => {
        const others = LANES.filter((n) => n !== axis && (!restrictGreater || n > axis));
        return (
          <div key={axis} className="shrink-0 w-28 bg-base border border-line rounded-md overflow-hidden">
            <AxisHeader axis={axis} name={boatNames?.[axis - 1] || ""} />
            {!others.length && <div className="text-center py-2 text-[10px] text-weak">―</div>}
            {others.map((other) => {
              const key = comboKey(type, [axis, other]);
              return (
                <OddsRow
                  key={other}
                  lane={other}
                  value={odds[key]}
                  isRange={isRange}
                  selected={selected.has(key)}
                  onToggle={() => toggle(key)}
                />
              );
            })}
          </div>
        );
      })}
    </div>
  );
}

/**
 * 3連複: 軸（最小艇番）ごとに、軸より大きい艇番から2着候補を選び、
 * さらにそれより大きい艇番を3着候補とすることで、重複の無い組み合わせに
 * している（公式サイトと同じ列挙方式）。
 */
function TrioAxisBoard({ odds, boatNames, selected, toggle }) {
  return (
    <div className="flex gap-1.5 overflow-x-auto pb-1">
      {LANES.map((axis) => {
        const remaining = LANES.filter((n) => n > axis);
        const groups = remaining
          .map((second) => ({ second, thirds: remaining.filter((n) => n > second) }))
          .filter((g) => g.thirds.length);
        return (
          <div key={axis} className="shrink-0 w-32 bg-base border border-line rounded-md overflow-hidden">
            <AxisHeader axis={axis} name={boatNames?.[axis - 1] || ""} />
            {!groups.length && <div className="text-center py-2 text-[10px] text-weak">―</div>}
            {groups.map(({ second, thirds }) => (
              <div key={second} className="flex border-t border-line">
                <div className="w-6 shrink-0 flex items-center justify-center border-r border-line">
                  <LaneBadge lane={second} size="xs" />
                </div>
                <div className="flex-1">
                  {thirds.map((third, i) => {
                    const key = comboKey("trio", [axis, second, third]);
                    return (
                      <OddsRow
                        key={third}
                        lane={third}
                        value={odds[key]}
                        selected={selected.has(key)}
                        onToggle={() => toggle(key)}
                        borderTop={i > 0}
                      />
                    );
                  })}
                </div>
              </div>
            ))}
          </div>
        );
      })}
    </div>
  );
}

/**
 * 3連単: 軸（1着候補）ごとのブロック内で、2着候補ごとに
 *   - その2連単オッズ（実際の売買オッズ）
 *   - 残り3着ぶんの3連単オッズをすべて合成した場合のオッズ（参考値）
 * を見出しとして出し、その下に内訳の3連単オッズ（3着ごと）を並べる。
 * 合成オッズが2連単の実オッズより低ければ2連単の方が有利、
 * 逆に高ければ3連単を割ったほうが有利……という目安になる。
 */
function TrifectaAxisBoard({ boatNames, trifectaOdds, exactaOdds, selected, toggle }) {
  return (
    <div className="flex gap-1.5 overflow-x-auto pb-1">
      {LANES.map((axis) => {
        const seconds = LANES.filter((n) => n !== axis);
        return (
          <div key={axis} className="shrink-0 w-32 bg-base border border-line rounded-md overflow-hidden">
            <AxisHeader axis={axis} name={boatNames?.[axis - 1] || ""} />
            {seconds.map((second) => {
              const thirds = LANES.filter((n) => n !== axis && n !== second);
              const exOdds = exactaOdds[comboKey("exacta", [axis, second])];
              const triList = thirds
                .map((third) => trifectaOdds[comboKey("trifecta", [axis, second, third])])
                .filter((v) => Number.isFinite(v));
              const synth = syntheticOdds(triList);

              return (
                <div key={second} className="border-t border-line">
                  <div className="flex items-center justify-between gap-1 px-1.5 py-1 bg-panel">
                    <span className="flex items-center gap-1 text-[9px] text-sub2">
                      <LaneBadge lane={second} size="xs" />2連単
                    </span>
                    <span className="text-right leading-tight">
                      <div className="text-[11px] font-bold tabular-nums" style={{ color: oddsBandColor(exOdds).bg }}>
                        {Number.isFinite(exOdds) ? exOdds.toFixed(1) : "―"}
                      </div>
                      <div className="text-[8px] text-sub2 tabular-nums">{synth ? `合成${synth.toFixed(2)}` : "合成―"}</div>
                    </span>
                  </div>
                  {thirds.map((third) => {
                    const key = comboKey("trifecta", [axis, second, third]);
                    return (
                      <OddsRow
                        key={third}
                        lane={third}
                        value={trifectaOdds[key]}
                        selected={selected.has(key)}
                        onToggle={() => toggle(key)}
                        borderTop={false}
                      />
                    );
                  })}
                </div>
              );
            })}
          </div>
        );
      })}
    </div>
  );
}

export default function OddsPanel({ boatNames, stadium, raceNo, ymd }) {
  const [category, setCategory] = useState("sanren");
  const [singleSub, setSingleSub] = useState("win");
  const [nirenSub, setNirenSub] = useState("exacta");
  const [sanrenSub, setSanrenSub] = useState("trifecta");
  // odds[betType][comboKey] = number（複勝・拡連複は下限値の数値。実際の幅は rangeText 参照）
  const [allOdds, setAllOdds] = useState({});
  const [rangeText, setRangeText] = useState({}); // { place: "1: 1.3-1.5　2: ...", quinella_place: "..." }
  const [selected, setSelected] = useState(() => new Set());

  const [autoLoading, setAutoLoading] = useState(false);
  const [autoError, setAutoError] = useState(null);
  const [autoWarnings, setAutoWarnings] = useState([]);

  const canAutoFetch = Boolean(stadium && raceNo && ymd);

  const fetchAutoOdds = async () => {
    if (!canAutoFetch) return;
    setAutoLoading(true);
    setAutoError(null);
    setAutoWarnings([]);
    try {
      const url = `${PROXY_BASE}/api/odds/all?stadium=${stadium}&hd=${ymd}&rno=${raceNo}`;
      const res = await fetch(url);
      const data = await res.json().catch(() => null);
      if (!res.ok) throw new Error(data?.error || `HTTP ${res.status}`);
      if (!data) throw new Error("応答を解釈できませんでした");
      if (data.noData) {
        setAutoError("公式サイトにまだオッズが出ていません（発売前・締切直後などの可能性があります）。");
        return;
      }

      const next = {};
      const nextRangeText = {};

      if (data.win) next.win = Object.fromEntries(Object.entries(data.win).filter(([, v]) => Number.isFinite(v)));
      if (data.place) {
        const entries = Object.entries(data.place).filter(([, v]) => v);
        next.place = Object.fromEntries(entries.map(([lane, range]) => [lane, lowerBoundOf(range)]));
        if (entries.length) nextRangeText.place = entries.map(([lane, range]) => `${lane}: ${range}`).join("　");
      }
      for (const type of ["exacta", "quinella", "trifecta", "trio"]) {
        if (data[type]) next[type] = Object.fromEntries(Object.entries(data[type]).filter(([, v]) => Number.isFinite(v)));
      }
      if (data.quinella_place) {
        const entries = Object.entries(data.quinella_place).filter(([, v]) => v);
        next.quinella_place = Object.fromEntries(entries.map(([k, range]) => [k, lowerBoundOf(range)]));
        if (entries.length) nextRangeText.quinella_place = entries.map(([k, range]) => `${k}: ${range}`).join("　");
      }

      setAllOdds((prev) => {
        const merged = { ...prev };
        for (const [type, vals] of Object.entries(next)) merged[type] = { ...(merged[type] || {}), ...vals };
        return merged;
      });
      setRangeText((prev) => ({ ...prev, ...nextRangeText }));

      const gotAny = Object.values(next).some((o) => Object.keys(o).length > 0);
      const failedPages = Object.entries(data.errors || {}).map(([page, e]) => `${page}: ${e.error}`);
      if (!gotAny) {
        setAutoError("取得はできましたが、数値を読み取れませんでした。ページ構成が変わった可能性があります。");
      } else if (failedPages.length) {
        setAutoWarnings(failedPages);
      }
    } catch (e) {
      setAutoError(
        `取得できませんでした（${String(e.message || e)}）。取得用プロキシ（ローカルなら uipath-server を node index.js で起動、または .env の REACT_APP_PROXY_BASE でデプロイ済みのプロキシを指定）を確認してください。ブロックされている場合は手入力・貼り付けを使ってください。`
      );
    } finally {
      setAutoLoading(false);
    }
  };

  // オッズタブを開いたとき、および開催場・レース・日付が変わったときに自動取得する
  useEffect(() => {
    setAllOdds({});
    setRangeText({});
    setSelected(new Set());
    setAutoError(null);
    setAutoWarnings([]);
    if (stadium && raceNo && ymd) fetchAutoOdds();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [stadium, raceNo, ymd]);

  const type = category === "single" ? singleSub : category === "niren" ? nirenSub : sanrenSub;
  const odds = allOdds[type] || {};

  const toggle = (key) =>
    setSelected((prev) => {
      const n = new Set(prev);
      n.has(key) ? n.delete(key) : n.add(key);
      return n;
    });

  const switchTo = (setter, val) => { setter(val); setSelected(new Set()); };

  const selectedOdds = useMemo(
    () => [...selected].map((k) => odds[k]).filter((v) => Number.isFinite(v) && v > 0),
    [selected, odds]
  );
  const synth = syntheticOdds(selectedOdds);

  return (
    <div>
      <Notice tone="warn">
        オッズと投票数はBoatraceOpenAPIに含まれないため、オッズタブを開くと取得用プロキシ経由で公式サイトから自動取得します。公式サイトのボット対策でブロックされる場合や、プロキシが動いていない場合は失敗するので、その場合は「再取得」を試してください。複勝・拡連複はオッズに幅があるため、一覧には下限値を表示しています（幅そのものは下の注記を参照）。
      </Notice>

      <div className="mt-3 flex items-center gap-2">
        <div className="flex-1 min-w-0 text-[11px]">
          {!canAutoFetch ? (
            <span className="text-weak">開催場・レースが選択されていないため自動取得できません。</span>
          ) : autoLoading ? (
            <span className="flex items-center gap-1.5 text-sub2"><Loader2 size={12} className="animate-spin" />公式サイトから取得中…</span>
          ) : autoError ? (
            <span className="text-[#E5433D] leading-relaxed">{autoError}</span>
          ) : (
            <span className="text-sub2">公式サイトから自動取得済み</span>
          )}
          {!!autoWarnings.length && (
            <div className="text-amber leading-relaxed mt-0.5">
              一部のページは取得できませんでした：{autoWarnings.join("　")}
            </div>
          )}
        </div>
        <button
          onClick={fetchAutoOdds}
          disabled={!canAutoFetch || autoLoading}
          className="shrink-0 flex items-center gap-1 text-[11px] font-semibold bg-panel border border-line text-sub px-2.5 py-1.5 rounded-md disabled:opacity-50 hover:border-accent"
        >
          <RefreshCw size={12} className={autoLoading ? "animate-spin" : ""} />再取得
        </button>
      </div>

      <div className="flex gap-1 mt-3">
        {[{ k: "single", l: "単複・拡連複" }, { k: "niren", l: "2連系" }, { k: "sanren", l: "3連系" }].map((c) => (
          <button key={c.k} onClick={() => { setCategory(c.k); setSelected(new Set()); }}
            className={"flex-1 py-1.5 rounded-md text-xs font-semibold border transition-colors " +
              (category === c.k ? "bg-accent border-accent text-base" : "bg-panel border-line text-sub")}>
            {c.l}
          </button>
        ))}
      </div>

      <div className="flex items-center gap-1 mt-2 flex-wrap">
        {category === "single" && [{ k: "win", l: "単勝" }, { k: "place", l: "複勝" }, { k: "quinella_place", l: "拡連複" }].map((s) => (
          <button key={s.k} onClick={() => switchTo(setSingleSub, s.k)}
            className={"px-2.5 py-1 rounded text-[11px] font-semibold border " +
              (singleSub === s.k ? "bg-amber border-amber text-base" : "bg-panel border-line text-sub")}>{s.l}</button>
        ))}
        {category === "niren" && [{ k: "exacta", l: "2連単" }, { k: "quinella", l: "2連複" }].map((s) => (
          <button key={s.k} onClick={() => switchTo(setNirenSub, s.k)}
            className={"px-2.5 py-1 rounded text-[11px] font-semibold border " +
              (nirenSub === s.k ? "bg-amber border-amber text-base" : "bg-panel border-line text-sub")}>{s.l}</button>
        ))}
        {category === "sanren" && [{ k: "trifecta", l: "3連単" }, { k: "trio", l: "3連複" }].map((s) => (
          <button key={s.k} onClick={() => switchTo(setSanrenSub, s.k)}
            className={"px-2.5 py-1 rounded text-[11px] font-semibold border " +
              (sanrenSub === s.k ? "bg-amber border-amber text-base" : "bg-panel border-line text-sub")}>{s.l}</button>
        ))}
      </div>

      <div className="flex flex-wrap gap-x-2.5 gap-y-1 mt-2 text-[9px] text-sub2">
        {ODDS_LEGEND.map(([l, hex]) => (
          <span key={l} className="flex items-center gap-1"><span className="w-2 h-2 rounded-sm" style={{ background: hex }} />{l}倍</span>
        ))}
      </div>

      <div className="mt-3">
        <div className="min-w-0">
          <div className="bg-panel border border-line rounded-lg p-2.5">
            {type === "trifecta" ? (
              <TrifectaAxisBoard
                boatNames={boatNames}
                trifectaOdds={odds}
                exactaOdds={allOdds.exacta || {}}
                selected={selected}
                toggle={toggle}
              />
            ) : type === "trio" ? (
              <TrioAxisBoard odds={odds} boatNames={boatNames} selected={selected} toggle={toggle} />
            ) : type === "win" || type === "place" ? (
              <SingleAxisBoard odds={odds} boatNames={boatNames} isRange={type === "place"} />
            ) : (
              <PairAxisBoard
                type={type}
                odds={odds}
                boatNames={boatNames}
                isRange={type === "quinella_place"}
                restrictGreater={!BET_TYPES[type].ordered}
                selected={selected}
                toggle={toggle}
              />
            )}
          </div>

          {rangeText[type] && (
            <div className="text-[10px] text-sub2 mt-1.5 leading-relaxed">
              幅のある表示（参考）：{rangeText[type]}
            </div>
          )}

          <div className="mt-3 bg-panel border border-line rounded-lg p-3">
            <div className="flex items-center gap-1.5 text-xs font-semibold text-ink mb-2">
              <Calculator size={13} className="text-accent" />合成オッズ
            </div>
            <div className="flex items-center justify-between">
              <span className="text-xs text-sub2">{BET_TYPES[type].label}・{selectedOdds.length}点選択中</span>
              <span className="text-sm font-bold tabular-nums text-amber">{synth ? `${synth.toFixed(2)}倍` : "―"}</span>
            </div>
            {synth && (
              <div className="text-[10px] text-weak text-right mt-0.5">
                全点均等に計100円 → 的中時 約{(synth * 100).toFixed(0)}円
              </div>
            )}
            <div className="text-[10px] text-weak mt-2 leading-relaxed">
              オッズの行（またはマス）をタップすると選択できます。合成オッズ = 1 ÷ Σ(1 ÷ 各点のオッズ)。
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
